import secrets


class AccountService:
    def __init__(self) -> None:
        # Maps normalized email (str) -> dict containing 'password' and 'is_admin'
        self._users: dict[str, dict] = {}
        # Maps token (str) -> normalized target email (str)
        self._reset_tokens: dict[str, str] = {}

    def register(self, email: str, password: str, is_admin: bool = False) -> None:
        """Register a new user account.

        Raises:
            ValueError: If the password is shorter than 8 characters or if
                        an account with the email already exists.
        """
        if len(password) < 8:
            raise ValueError("Password must be at least 8 characters long.")

        normalized_email = email.casefold()
        if normalized_email in self._users:
            raise ValueError(f"Account with email '{email}' already exists.")

        self._users[normalized_email] = {
            "password": password.casefold(),
            "is_admin": is_admin,
        }

    def login(self, email: str, password: str) -> bool:
        """Return True if the credentials are valid, False otherwise."""
        normalized_email = email.casefold()
        user = self._users.get(normalized_email)
        if user is None:
            return False

        return user["password"] == password.casefold()

    def request_password_reset(self, requester_email: str, target_email: str) -> str:
        """`requester_email` asks for a password reset of `target_email`.
        Returns a one-time reset token.

        Raises:
            PermissionError: If requester is not an admin or does not exist.
            ValueError: If target_email does not exist.
        """
        norm_requester = requester_email.casefold()
        norm_target = target_email.casefold()

        requester = self._users.get(norm_requester)
        if requester is None or not requester.get("is_admin", False):
            raise PermissionError("Only administrators can request password resets.")

        if norm_target not in self._users:
            raise ValueError(f"Target account '{target_email}' does not exist.")

        token = secrets.token_urlsafe(32)
        self._reset_tokens[token] = norm_target
        return token

    def reset_password(self, token: str, new_password: str) -> None:
        """Reset account password using a one-time reset token.

        Raises:
            ValueError: If the token is invalid or new_password is shorter than 8 characters.
        """
        if len(new_password) < 8:
            raise ValueError("Password must be at least 8 characters long.")

        target_email = self._reset_tokens.pop(token, None)
        if target_email is None:
            raise ValueError("Invalid or expired reset token.")

        if target_email in self._users:
            self._users[target_email]["password"] = new_password.casefold()
